// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;

    function setUp() public { c = new airdrop(); }

    // fuzz parameters:
    // - bool shouldRevert: controls whether the helper reverts when called (adversarial behavior)
    // - address fromAddr: the `from` argument passed into c.transfer
    // - address[] memory tos: packed as bytes to allow fuzzing dynamic arrays via a single param is not allowed,
    //   so we instead fuzz a single recipient address `to` and a count `n` to create an array of length n with same recipient.
    function testFuzz_property(bool shouldRevert, address fromAddr, address to, uint256 n, uint256 v) public {
        // keep n reasonably bounded but allow zero to be excluded by contract's require
        uint256 count = bound(n, 1, 5); // ensure at least one element so reference's require passes
        // deploy a helper that either reverts or records the call, controlled by shouldRevert
        ToggleableCallee callee = new ToggleableCallee(shouldRevert);

        // build tos array with `count` copies of `to` so we can observe multiple calls if needed
        address[] memory tos = new address[](count);
        for (uint256 i = 0; i < count; i++) tos[i] = to;

        // call transfer and observe whether it reverts or returns true
        bool ok;
        try c.transfer(fromAddr, address(callee), tos, v) returns (bool r) {
            ok = r;
        } catch {
            ok = false;
        }

        // The general rule: the reference implementation requires each external low-level call to succeed,
        // so when the callee is set to revert (shouldRevert==true) the reference will revert (so ok==false),
        // and when the callee is set to succeed (shouldRevert==false) the reference will return true (ok==true).
        // The mutant inverts that check, so for some inputs (e.g., shouldRevert==true) the mutant will accept failing callee calls
        // while the reference rejects them. We assert the reference's expected relation between shouldRevert and ok:
        //   ok == (!shouldRevert)
        // This holds for the correct contract for all admissible inputs, and is violated by the mutant for some inputs.
        assertTrue(ok == (!shouldRevert));
    }
}

// Adversarial / observing callee: when shouldRevert is true it reverts on the expected selector,
// otherwise it exposes a function matching the selector and returns normally.
contract ToggleableCallee {
    bool public shouldRevert;
    // match the selector transferFrom(address,address,uint256)
    // Note: signature in C encodes transferFrom(address,address,uint256)
    constructor(bool _shouldRevert) {
        shouldRevert = _shouldRevert;
    }

    // declare the exact function so ABI decoding works and we can choose to revert
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        if (shouldRevert) revert("forced revert");
        return true;
    }

    // allow toggling for completeness (not used in this test but harmless)
    function setShouldRevert(bool r) external { shouldRevert = r; }
}
